def resolve(name: str) -> str:
    """The icon a project alias stands for (``settings.COREUI_ICON_ALIASES``); other names pass through unchanged."""
    return getattr(settings, "COREUI_ICON_ALIASES", {}).get(name, name)


def svg(name: str | None, css: str = "") -> SafeString:
    """Inline SVG for a CoreUI icon name; empty for no name or one not in ``ICONS``."""
    if not name or name not in ICONS:
        return SafeString("")
    return format_html(
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" aria-hidden="true" focusable="false" '
        'class="{}">{}</svg>',
        f"icon {css}".strip(),
        mark_safe(ICONS[name]),
    )
